-- S11 cursors (13.1 declare cursor / 13.2 open / 13.3 fetch / 13.4 close / 13.6 positioned delete / 13.9 positioned update): whether the statements are accepted
-- @s11_13_1_declare_fetch_close
BEGIN; DECLARE c1 CURSOR FOR SELECT empnum, empname FROM t92_staff ORDER BY empnum; FETCH NEXT FROM c1; FETCH NEXT FROM c1; CLOSE c1; COMMIT;
-- @s11_13_3_fetch_count
BEGIN; DECLARE c1 CURSOR FOR SELECT empnum FROM t92_staff ORDER BY empnum; FETCH 3 FROM c1; FETCH ALL FROM c1; CLOSE c1; COMMIT;
-- @s11_13_3_fetch_past_end
BEGIN; DECLARE c1 CURSOR FOR SELECT empnum FROM t92_staff WHERE empnum = 'E1'; FETCH NEXT FROM c1; FETCH NEXT FROM c1; CLOSE c1; COMMIT;
-- @s11_13_9_update_where_current_of
DROP TABLE IF EXISTS t92_w11_c04; CREATE TABLE t92_w11_c04 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w11_c04 VALUES (1, 1); INSERT INTO t92_w11_c04 VALUES (2, 2); BEGIN; DECLARE c1 CURSOR FOR SELECT id, a FROM t92_w11_c04 WHERE id = 1 FOR UPDATE; FETCH NEXT FROM c1; UPDATE t92_w11_c04 SET a = 100 WHERE CURRENT OF c1; CLOSE c1; COMMIT; SELECT * FROM t92_w11_c04; DROP TABLE t92_w11_c04;
-- @s11_13_6_delete_where_current_of
DROP TABLE IF EXISTS t92_w11_c05; CREATE TABLE t92_w11_c05 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w11_c05 VALUES (1, 1); INSERT INTO t92_w11_c05 VALUES (2, 2); BEGIN; DECLARE c1 CURSOR FOR SELECT id, a FROM t92_w11_c05 WHERE id = 2 FOR UPDATE; FETCH NEXT FROM c1; DELETE FROM t92_w11_c05 WHERE CURRENT OF c1; CLOSE c1; COMMIT; SELECT * FROM t92_w11_c05; DROP TABLE t92_w11_c05;
-- @s11_select_for_update
BEGIN; SELECT empname FROM t92_staff WHERE empnum = 'E1' FOR UPDATE; COMMIT;
